from openpyxl import load_workbook

wb = load_workbook('book.xlsx')

print("Workbook-level defined names:")
for defined_name in wb.defined_names.definedName:
    print(f"  {defined_name.name}: {defined_name.value}")

print("\nSheet-level defined names:")
for ws_name in wb.sheetnames:
    ws = wb[ws_name]
    if hasattr(ws, 'defined_names') and ws.defined_names:
        print(f"  {ws_name}:")
        for defined_name in ws.defined_names.definedName:
            print(f"    {defined_name.name}: {defined_name.value}")
    else:
        print(f"  {ws_name}: (no defined names)")

